def hasCircularLoop(nums):
    n = len(nums)
    nxt = [-1] * n
    for i in range(n):
        j = (i + nums[i]) % n
        if j != i and (nums[j] > 0) == (nums[i] > 0):
            nxt[i] = j
    mark = [0] * n
    for s in range(n):
        if mark[s]:
            continue
        walk = s + 1
        i = s
        while i != -1 and mark[i] == 0:
            mark[i] = walk
            i = nxt[i]
        if i != -1 and mark[i] == walk:
            return True
    return False
